using JiraClone.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace JiraClone.Api.Data;

public sealed class JiraDbContext(DbContextOptions<JiraDbContext> options) : DbContext(options)
{
    public DbSet<User> Users => Set<User>(); public DbSet<RefreshToken> RefreshTokens => Set<RefreshToken>(); public DbSet<Project> Projects => Set<Project>(); public DbSet<ProjectMember> ProjectMembers => Set<ProjectMember>(); public DbSet<Sprint> Sprints => Set<Sprint>(); public DbSet<Issue> Issues => Set<Issue>(); public DbSet<IssueComment> IssueComments => Set<IssueComment>(); public DbSet<IssueActivity> IssueActivities => Set<IssueActivity>(); public DbSet<IssueNumberSequence> IssueNumberSequences => Set<IssueNumberSequence>(); public DbSet<IssueLabel> IssueLabels => Set<IssueLabel>(); public DbSet<IssueWatcher> IssueWatchers => Set<IssueWatcher>(); public DbSet<IssueComponent> IssueComponents => Set<IssueComponent>(); public DbSet<IssueRelationship> IssueRelationships => Set<IssueRelationship>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<User>().HasIndex(x => x.Email).IsUnique(); modelBuilder.Entity<Project>().HasIndex(x => x.Key).IsUnique(); modelBuilder.Entity<Issue>().HasIndex(x => new { x.ProjectId, x.Number }).IsUnique(); modelBuilder.Entity<RefreshToken>().HasIndex(x => x.TokenHash).IsUnique(); modelBuilder.Entity<RefreshToken>().Property(x => x.TokenHash).HasMaxLength(64).IsRequired(); modelBuilder.Entity<RefreshToken>().Property(x => x.ReplacedByTokenHash).HasMaxLength(64); modelBuilder.Entity<RefreshToken>().HasOne(x => x.User).WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Cascade);
        modelBuilder.Entity<Issue>().Property(x => x.Status).HasConversion<string>(); modelBuilder.Entity<Issue>().Property(x => x.Priority).HasConversion<string>(); modelBuilder.Entity<Issue>().Property(x => x.Type).HasConversion<string>(); modelBuilder.Entity<Sprint>().Property(x => x.Status).HasConversion<string>(); modelBuilder.Entity<IssueActivity>().Property(x => x.Type).HasConversion<string>(); modelBuilder.Entity<User>().Property(x => x.Role).HasMaxLength(32).IsRequired(); modelBuilder.Entity<ProjectMember>().Property(x => x.Role).HasConversion<string>(); modelBuilder.Entity<IssueRelationship>().Property(x => x.Type).HasConversion<string>();
        modelBuilder.Entity<ProjectMember>().HasKey(x => new { x.ProjectId, x.UserId }); modelBuilder.Entity<ProjectMember>().HasOne(x => x.Project).WithMany(x => x.Members).HasForeignKey(x => x.ProjectId).OnDelete(DeleteBehavior.Cascade); modelBuilder.Entity<ProjectMember>().HasOne(x => x.User).WithMany(x => x.ProjectMemberships).HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Cascade);
        modelBuilder.Entity<IssueNumberSequence>().HasKey(x => x.ProjectId); modelBuilder.Entity<IssueNumberSequence>().Property(x => x.NextNumber).IsRequired(); modelBuilder.Entity<IssueNumberSequence>().HasOne<Project>().WithMany().HasForeignKey(x => x.ProjectId).OnDelete(DeleteBehavior.Cascade);
        modelBuilder.Entity<Issue>().HasOne(x => x.Project).WithMany(x => x.Issues).HasForeignKey(x => x.ProjectId).OnDelete(DeleteBehavior.Cascade); modelBuilder.Entity<Sprint>().HasOne(x => x.Project).WithMany(x => x.Sprints).HasForeignKey(x => x.ProjectId).OnDelete(DeleteBehavior.Cascade); modelBuilder.Entity<Issue>().HasOne(x => x.Assignee).WithMany().HasForeignKey(x => x.AssigneeId).OnDelete(DeleteBehavior.SetNull); modelBuilder.Entity<Issue>().HasOne(x => x.Sprint).WithMany(x => x.Issues).HasForeignKey(x => x.SprintId).OnDelete(DeleteBehavior.SetNull); modelBuilder.Entity<IssueComment>().HasOne(x => x.Issue).WithMany(x => x.Comments).HasForeignKey(x => x.IssueId).OnDelete(DeleteBehavior.Cascade); modelBuilder.Entity<IssueComment>().HasOne(x => x.Author).WithMany().HasForeignKey(x => x.AuthorId).OnDelete(DeleteBehavior.Restrict); modelBuilder.Entity<IssueActivity>().HasOne(x => x.Issue).WithMany(x => x.Activities).HasForeignKey(x => x.IssueId).OnDelete(DeleteBehavior.Cascade); modelBuilder.Entity<IssueActivity>().HasOne(x => x.Actor).WithMany().HasForeignKey(x => x.ActorId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<IssueLabel>().ToTable("Labels"); modelBuilder.Entity<IssueLabel>().HasIndex(x => new { x.ProjectId, x.Name }).IsUnique(); modelBuilder.Entity<IssueLabel>().HasOne(x => x.Project).WithMany(x => x.Labels).HasForeignKey(x => x.ProjectId).OnDelete(DeleteBehavior.Cascade); modelBuilder.Entity<IssueLabel>().HasMany(x => x.Issues).WithMany(x => x.Labels).UsingEntity(j => j.ToTable("IssueLabelLinks"));
        modelBuilder.Entity<IssueWatcher>().HasKey(x => new { x.IssueId, x.UserId }); modelBuilder.Entity<IssueWatcher>().HasOne(x => x.Issue).WithMany(x => x.Watchers).HasForeignKey(x => x.IssueId).OnDelete(DeleteBehavior.Cascade); modelBuilder.Entity<IssueWatcher>().HasOne(x => x.User).WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<IssueComponent>().ToTable("Components"); modelBuilder.Entity<IssueComponent>().HasIndex(x => new { x.ProjectId, x.Name }).IsUnique(); modelBuilder.Entity<IssueComponent>().HasOne(x => x.Project).WithMany(x => x.Components).HasForeignKey(x => x.ProjectId).OnDelete(DeleteBehavior.Cascade); modelBuilder.Entity<IssueComponent>().HasMany(x => x.Issues).WithMany(x => x.Components).UsingEntity(j => j.ToTable("IssueComponentLinks"));
        modelBuilder.Entity<IssueRelationship>().HasIndex(x => new { x.SourceIssueId, x.TargetIssueId, x.Type }).IsUnique(); modelBuilder.Entity<IssueRelationship>().HasOne(x => x.SourceIssue).WithMany().HasForeignKey(x => x.SourceIssueId).OnDelete(DeleteBehavior.Cascade); modelBuilder.Entity<IssueRelationship>().HasOne(x => x.TargetIssue).WithMany().HasForeignKey(x => x.TargetIssueId).OnDelete(DeleteBehavior.Restrict); modelBuilder.Entity<IssueRelationship>().HasOne(x => x.CreatedBy).WithMany().HasForeignKey(x => x.CreatedById).OnDelete(DeleteBehavior.Restrict);
    }
}
